  "cuisine_type": "South Indian (Keralan Vegetarian)",
  "review_count": 1048,
  "average_rating": 4.4,
  "summary": "Established in 1997 by Das Sreedharan, Rasa N16 is a pioneering, iconic London institution located at 55 Stoke Newington Church St. It is highly celebrated for introducing authentic, uncompromising Keralan vegetarian cuisine to the UK. Operating behind its distinctive shocking pink facade, Rasa focuses on the coastal and agrarian culinary heritage of Kerala, heavily emphasizing fresh coconut, mustard seeds, tamarind, curry leaves, and regional gourds. It remains a beloved local hub that completely avoids the sweet, cream-heavy tropes of generic British-Indian restaurants, maintaining excellent value and deep geographic specificity.",
  "match_score": 94,
  "value_and_volume": {
    "score": 9,
    "description": "Rasa offers exceptional value for money, classified as inexpensive while delivering generous, feast-like portions. The menu is built around highly affordable pre-meal snack platters (served with home-made pickles and spicy chutneys), hearty vegetable curries, and large, thin dosas that provide a deeply filling, high-quality communal dining experience."
  },
  "demographic_and_community_signal": {
    "score": 9,
    "description": "An absolute neighborhood anchor in Stoke Newington for over a quarter of a century. Rasa has successfully cultivated a deeply loyal base of local residents, vegetarians, and South Asian culinary purists rather than catering to transient tourists. It serves as a genuine community cultural hub."
  },
  "linguistic_and_insider_signal": {
    "score": 9,
    "description": "The menu proudly avoids generic anglicized labels, opting for untranslated Malayalam culinary terms. Dishes are presented under their authentic regional names (e.g., 'Moru Kachiathu', 'Cheera Parippu Curry', 'Olan', 'Thorans'). The frontline kitchen and waiting staff are highly knowledgeable and native to South India, preserving authentic cultural and linguistic continuity."
  },
  "geographic_precision": {
    "score": 10,
    "description": "Superb regional specificity. Rasa N16 specializes exclusively in the vegetarian cuisine of Kerala, a state in Southwestern India. The kitchen celebrates hyper-local Keralan staples like green plantains, yams, ash gourds, coconut oil, and specialty rices, completely omitting standard pan-Indian curries or generic North Indian tandoori dishes."
  },
  "culinary_uncompromisingness": {
    "score": 9,
    "description": "Highly uncompromising. Rasa rejects standard, westernized, sugary gravies in favor of complex, tangy, and earthy flavor profiles. Dishes like 'Moru Kachiathu' (sour buttermilk boiled with turmeric, ginger, and green chillies) showcase the authentic, sour, and bitter taste profiles intrinsic to traditional home-cooked Keralan meals, resisting any watering down for Western palates."
  },
  "establishment_integrity": {
    "score": 10,
    "description": "A historic, dedicated sit-down dining establishment that has preserved its identity and physical location since the late 1990s. It completely avoids the quick-service, bakery, or cafe model, prioritizing a slow, hosted, and traditional communal dining experience in a classic restaurant setting."
  }
}

